INSERT INTO note (note_id,subject_id,note_name,note_path,note_desc,note_extension,is_delete,is_active,created_by,created_date,modified_by,modified_date,ip_address) VALUES ('316','91','English Articles of grammer','notes/1695978744251.pdf','In English there are three articles: a, an, and the. Articles are used before nouns or noun equivalents and are a type of adjective. The definite article (the) is used before a noun to indicate that the identity of the noun is known to the reader.','pdf','0','1',NULL,'2023-09-29 14:42:24',NULL,'2023-09-29 09:12:24',NULL);
INSERT INTO note (note_id,subject_id,note_name,note_path,note_desc,note_extension,is_delete,is_active,created_by,created_date,modified_by,modified_date,ip_address) VALUES ('317','91','English grammer adjective','notes/1695978807529.pdf','An adjective is a word that modifies or describes a noun or pronoun. Adjectives can be used to describe the qualities of someone or something independently or in comparison to something else. Examples: Adjectives in a sentence I like old houses. ','pdf','0','1',NULL,'2023-09-29 14:43:27',NULL,'2023-09-29 09:13:27',NULL);
